css:
#tongsci1-3-3-2-1-rbc .rb-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #e2e7ea; }
#tongsci1-3-3-2-1-rbc .rb-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-2-1-rbc .rb-panel { gap: 10px; }
#tongsci1-3-3-2-1-rbc .rb-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.4em; flex: none; transition: background .2s; }
#tongsci1-3-3-2-1-rbc .rb-out.bad { background: #ffe1dc; }
#tongsci1-3-3-2-1-rbc .rb-out .rb-ok, #tongsci1-3-3-2-1-rbc .rb-tab .rb-ok { color: var(--good); }
#tongsci1-3-3-2-1-rbc .rb-out .rb-no, #tongsci1-3-3-2-1-rbc .rb-tab .rb-no { color: #b23a22; }
#tongsci1-3-3-2-1-rbc .rb-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 16px/1.25 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-2-1-rbc .rb-tab thead th { font: 800 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-2-1-rbc .rb-tab thead th:nth-child(1) { width: 27%; }
#tongsci1-3-3-2-1-rbc .rb-tab thead th:nth-child(2) { width: 19%; }
#tongsci1-3-3-2-1-rbc .rb-tab thead th:nth-child(3) { width: 29%; }
#tongsci1-3-3-2-1-rbc .rb-tab tbody th { font: 700 15px/1.2 var(--f-body); text-align: left; padding: 3px 6px; border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); }
#tongsci1-3-3-2-1-rbc .rb-tab tbody th small { display: block; font: 600 13px var(--f-body); color: var(--accent); }
#tongsci1-3-3-2-1-rbc .rb-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 5px; height: 36px; text-align: center; }
#tongsci1-3-3-2-1-rbc .rb-tab tr.rb-sep th { text-align: left; font: 800 15px var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); }
#tongsci1-3-3-2-1-rbc .rb-pc { display: inline-block; padding: 0 8px; border: 1.5px solid var(--ink); border-radius: 6px; background: #fffdf2; font-weight: 700; }
#tongsci1-3-3-2-1-rbc .rb-photo { margin: 0; flex: none; border: 2px solid var(--ink); border-radius: 10px; overflow: hidden; background: #111; }
#tongsci1-3-3-2-1-rbc .rb-photo[hidden] { display: none; }
#tongsci1-3-3-2-1-rbc .rb-photo img { display: block; width: 100%; height: 118px; object-fit: cover; }
#tongsci1-3-3-2-1-rbc .rb-photo figcaption { background: var(--paper-2); font: 600 15px/1.3 var(--f-body); padding: 4px 10px; color: var(--ink-2); }
#tongsci1-3-3-2-1-rbc .rb-photo figcaption span { font-weight: 800; color: var(--accent); margin-right: 6px; }
#tongsci1-3-3-2-1-rbc .rb-photo figcaption small { display: block; font-size: 12px; color: var(--ink-3); }
#tongsci1-3-3-2-1-rbc.u-done .rb-out { display: none; }

